import type { MotionActivityBandView } from '~/client';
import { getMotionActivityColor, getMotionActivityLabel } from '~/constants/motionActivityColors';

// Visibility floor: a band shorter than ~0.05% of the visible range (≈ 0.5 px on a
// 1000-px track) would otherwise render as a sub-pixel sliver. The tooltip still
// reports the true duration, so the floor only inflates the *visual* width.
const MIN_BAR_WIDTH_PCT = 0.05;

export interface Range {
  startMs: number;
  endMs: number;
}

export interface MotionActivityBar {
  activity: string;
  leftPct: number;
  widthPct: number;
  color: string;
  tooltip: string;
}

// Activities reviewers care about as evidence of canvasser motion. When a cell mixes
// these with stationary/unknown, surface the foreground class — otherwise short walking
// or automotive bursts get swallowed by surrounding stationary at coarse zoom levels.
const FOREGROUND_ACTIVITIES = new Set(['walking', 'automotive', 'running', 'cycling']);
// Minimum share of a cell's total overlap that a foreground activity must hold to
// overrule a stationary/unknown majority. 5% ≈ "the canvasser was on foot for at least
// a few seconds inside this bucket"; below that, treat it as noise.
const FOREGROUND_MIN_RATIO = 0.05;

export function coarsenBands(
  bands: MotionActivityBandView[],
  range: Range,
  targetBuckets: number
): MotionActivityBandView[] {
  if (targetBuckets < 1) return bands;
  if (bands.length <= targetBuckets) return bands;
  const span = range.endMs - range.startMs;
  if (span <= 0) return [];

  const cellMs = span / targetBuckets;
  interface Cell {
    activity: string | null;
    confWeightedSum: number;
    weightMs: number;
  }
  const cells: Cell[] = new Array(targetBuckets);

  for (let i = 0; i < targetBuckets; i++) {
    const cellStart = range.startMs + i * cellMs;
    const cellEnd = cellStart + cellMs;
    const overlapByAct = new Map<string, number>();
    const confSumByAct = new Map<string, number>();
    let totalOverlap = 0;
    for (const b of bands) {
      const bStart = Date.parse(b.start_ts);
      const bEnd = Date.parse(b.end_ts);
      if (Number.isNaN(bStart) || Number.isNaN(bEnd)) continue;
      const overlap = Math.max(0, Math.min(bEnd, cellEnd) - Math.max(bStart, cellStart));
      if (overlap <= 0) continue;
      totalOverlap += overlap;
      overlapByAct.set(b.activity, (overlapByAct.get(b.activity) ?? 0) + overlap);
      confSumByAct.set(b.activity, (confSumByAct.get(b.activity) ?? 0) + b.avg_confidence * overlap);
    }
    let bestAct: string | null = null;
    let bestOverlap = 0;
    let bestForegroundAct: string | null = null;
    let bestForegroundOverlap = 0;
    for (const [a, o] of overlapByAct) {
      if (o > bestOverlap) {
        bestOverlap = o;
        bestAct = a;
      }
      if (FOREGROUND_ACTIVITIES.has(a) && o > bestForegroundOverlap) {
        bestForegroundOverlap = o;
        bestForegroundAct = a;
      }
    }
    // Foreground promotion: if a real motion class touched the cell (≥ 5% of total
    // overlap), surface it even when stationary/unknown dominates by majority.
    if (
      bestAct &&
      !FOREGROUND_ACTIVITIES.has(bestAct) &&
      bestForegroundAct &&
      totalOverlap > 0 &&
      bestForegroundOverlap / totalOverlap >= FOREGROUND_MIN_RATIO
    ) {
      bestAct = bestForegroundAct;
    }
    cells[i] = {
      activity: bestAct,
      confWeightedSum: bestAct ? (confSumByAct.get(bestAct) ?? 0) : 0,
      weightMs: bestAct ? (overlapByAct.get(bestAct) ?? 0) : 0,
    };
  }

  const out: MotionActivityBandView[] = [];
  let i = 0;
  while (i < cells.length) {
    if (cells[i].activity === null) {
      i++;
      continue;
    }
    let j = i;
    let confSum = 0;
    let weightSum = 0;
    while (j < cells.length && cells[j].activity === cells[i].activity) {
      confSum += cells[j].confWeightedSum;
      weightSum += cells[j].weightMs;
      j++;
    }
    const startMs = range.startMs + i * cellMs;
    const endMs = range.startMs + j * cellMs;
    out.push({
      activity: cells[i].activity as string,
      avg_confidence: weightSum > 0 ? confSum / weightSum : 0,
      start_ts: new Date(startMs).toISOString(),
      end_ts: new Date(endMs).toISOString(),
    });
    i = j;
  }
  return out;
}

function formatDuration(seconds: number): string {
  const s = Math.max(0, Math.round(seconds));
  const m = Math.floor(s / 60);
  const r = s - m * 60;
  if (m === 0) return `${r}s`;
  if (r === 0) return `${m}m`;
  return `${m}m ${r}s`;
}

export function buildMotionActivityBars(bands: MotionActivityBandView[], range: Range): MotionActivityBar[] {
  const span = range.endMs - range.startMs;
  if (!bands.length || span <= 0) return [];
  const out: MotionActivityBar[] = [];
  for (const b of bands) {
    const startMs = Date.parse(b.start_ts);
    const endMs = Date.parse(b.end_ts);
    if (Number.isNaN(startMs) || Number.isNaN(endMs)) continue;
    if (endMs < range.startMs || startMs > range.endMs) continue;
    const clipStart = Math.max(startMs, range.startMs);
    const clipEnd = Math.min(endMs, range.endMs);
    const durationS = Math.max(0, (endMs - startMs) / 1000);
    const label = getMotionActivityLabel(b.activity);
    out.push({
      activity: b.activity,
      leftPct: ((clipStart - range.startMs) / span) * 100,
      widthPct: Math.max(MIN_BAR_WIDTH_PCT, ((clipEnd - clipStart) / span) * 100),
      color: getMotionActivityColor(b.activity),
      tooltip: `${label} · ${formatDuration(durationS)} · conf ${Math.round(b.avg_confidence)}`,
    });
  }
  return out;
}
