<template>
  <div v-if="fraud" class="flex flex-col gap-2 mt-2 max-w-[300px]">
    <span :class="['self-start rounded-full px-2 py-0.5 text-[10px] font-semibold', severityChipClass]">
      {{ severityLabel }}
    </span>
    <div class="text-[12px] text-red-900 bg-red-50 rounded-md p-2 leading-snug">
      {{ fraud.summary }}
    </div>
    <div class="flex flex-col">
      <div
        v-for="(reason, idx) in fraud.reasons"
        :key="reason.code"
        :class="['grid grid-cols-[auto_1fr] gap-2 py-1.5', idx > 0 ? 'border-t border-border' : '']"
      >
        <span :class="['size-2 rounded-full mt-1.5', fraudSeverityConfig[reason.severity].dotBgClass]" />
        <div>
          <div class="text-[12px] font-semibold">{{ reason.label }}</div>
          <div class="text-[11px] text-muted-foreground mt-0.5 leading-snug">{{ reason.description }}</div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import type { InteractionFraudInfo } from '~/client';
import { fraudSeverityConfig } from '~/constants/reports/fraudReportCards';

interface Props {
  fraud: InteractionFraudInfo | null | undefined;
}
const props = defineProps<Props>();

const severityChipClass = computed(() => (props.fraud ? fraudSeverityConfig[props.fraud.severity].chipClass : ''));
