<template>
  <!-- Dense layout: no section labels/legends — the bars carry tooltips and
       the axis row below carries the time context. Brushing the track zooms. -->
  <div class="flex flex-col gap-1">
    <div v-if="isZoomed" class="flex justify-end">
      <button
        type="button"
        class="inline-flex items-center gap-1.5 rounded-md border border-border bg-background px-2 py-0.5 text-xs font-medium text-foreground shadow-sm hover:bg-muted/60 hover:border-foreground/30 transition-colors"
        @click="resetView"
      >
        <RotateCcwIcon class="h-3 w-3" />
        Reset Zoom
      </button>
    </div>

    <div
      ref="trackRef"
      :class="[
        'relative w-full select-none touch-none flex flex-col',
        brushState ? 'cursor-ew-resize' : 'cursor-crosshair',
      ]"
      @pointerdown="onTrackPointerDown"
      @pointermove="onTrackPointerMove"
      @pointerup="onTrackPointerUp"
      @pointercancel="onTrackPointerUp"
    >
      <div
        v-for="tick in hourTicks"
        :key="`tick-${tick.ms}`"
        class="absolute top-0 bottom-0 w-px bg-muted-foreground/15 pointer-events-none"
        :style="{ left: `${tick.leftPct}%` }"
      />

      <template v-if="interactions.length">
        <div class="relative h-8 w-full">
          <div
            class="absolute inset-x-0 top-1/2 h-2.5 -translate-y-1/2 rounded-full bg-gradient-to-r from-muted via-muted-foreground/15 to-muted shadow-inner"
          />
          <button
            v-for="event in visibleEvents"
            :key="`tl-${event.idx}`"
            type="button"
            :aria-label="`${formatResponseLabel(event.inter.response)} at ${formatDateTzToFormat(event.inter.ts, 'MM/dd, h:mm aaa', axisZone)}`"
            :class="[
              'absolute top-1/2 h-4 w-4 rounded-full border-2 border-white shadow-md cursor-pointer transition-all duration-150',
              'hover:scale-[1.5] hover:z-20',
              isDimmed(event.inter) ? 'opacity-30' : '',
              activeId === `interaction:${event.idx}`
                ? 'ring-2 ring-offset-1 ring-offset-background ring-foreground/50 scale-125'
                : '',
            ]"
            :style="{
              left: `${event.leftPct}%`,
              backgroundColor: event.inter.response_color,
              transform: 'translate(-50%, -50%)',
              zIndex: activeId === `interaction:${event.idx}` ? 10 : 2,
            }"
            :aria-current="activeId === `interaction:${event.idx}` ? 'true' : undefined"
            @pointerdown.stop
            @click.stop="emit('select', event.inter, event.idx)"
          >
            <span
              v-if="showEventLabels"
              class="pointer-events-none absolute bottom-full left-1/2 mb-0.5 -translate-x-1/2 whitespace-nowrap text-[10px] font-bold leading-none tabular-nums text-foreground"
            >
              {{ event.idx + 1 }}
            </span>
          </button>
        </div>
      </template>

      <template v-if="motionActivityBars.length">
        <div
          class="relative h-3.5 w-full overflow-hidden rounded-sm bg-muted/40 border border-border/40"
          :class="interactions.length ? 'mt-1' : ''"
        >
          <div
            v-for="(bar, i) in motionActivityBars"
            :key="`motion-${i}`"
            class="absolute top-0 bottom-0"
            :title="bar.tooltip"
            :style="{
              left: `${bar.leftPct}%`,
              width: `${bar.widthPct}%`,
              backgroundColor: bar.color,
              opacity: 0.9,
            }"
          />
        </div>
      </template>

      <template v-if="parsedSegments.length">
        <div
          class="relative h-3.5 w-full overflow-hidden rounded-sm bg-muted/40 border border-border/40"
          :class="interactions.length || motionActivityBars.length ? 'mt-1' : ''"
        >
          <div
            v-for="seg in segmentBars"
            :key="`seg-${seg.id}`"
            class="absolute top-0 bottom-0"
            :title="seg.tooltip"
            :style="{
              left: `${seg.leftPct}%`,
              width: `${seg.widthPct}%`,
              backgroundColor: seg.color,
              opacity: 0.9,
            }"
          />
        </div>
      </template>

      <div
        v-if="brushOverlay"
        class="absolute top-0 bottom-0 bg-foreground/10 border-x-2 border-foreground/50 pointer-events-none"
        :style="{ left: `${brushOverlay.leftPct}%`, width: `${brushOverlay.widthPct}%` }"
      />
    </div>

    <div class="relative h-5 text-xs text-muted-foreground tabular-nums">
      <span class="absolute left-0 top-0">{{ startLabel }}</span>
      <span
        v-for="tick in hourTicks"
        :key="`label-${tick.ms}`"
        class="absolute top-0 -translate-x-1/2 whitespace-nowrap"
        :style="{ left: `${tick.leftPct}%` }"
      >
        {{ tick.label }}
      </span>
      <span class="absolute right-0 top-0">{{ endLabel }}</span>
    </div>
  </div>
</template>

<script setup lang="ts">
import { useElementSize } from '@vueuse/core';
import type { InteractionPointView, MotionActivityBandView, RouteSegmentView } from '~/client';
import { buildMotionActivityBars, coarsenBands } from '~/utils/canvassing/motionActivityBands';
import { RotateCcwIcon } from 'lucide-vue-next';
import { scoreToColor } from '~/utils/canvassing/segmentScore';
import { formatResponseLabel } from '~/utils/canvassing/format';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';

interface Props {
  interactions: InteractionPointView[];
  routeSegments?: RouteSegmentView[];
  motionActivitySegments?: MotionActivityBandView[];
  selectedResponses?: string[];
  activeId?: string | null;
  // IANA timezone for the axis labels. Pass the shift's own time zone so the
  // axis matches the interaction tables; falls back to the viewer's timezone.
  timezone?: string;
}
const props = withDefaults(defineProps<Props>(), {
  routeSegments: () => [],
  motionActivitySegments: () => [],
  selectedResponses: () => [],
  activeId: null,
  timezone: undefined,
});

const emit = defineEmits<{
  (e: 'select', inter: InteractionPointView, idx: number): void;
  (e: 'window-change', window: { start: Date; end: Date } | null): void;
}>();

interface Range {
  startMs: number;
  endMs: number;
}

interface ParsedInteraction {
  inter: InteractionPointView;
  idx: number;
  ms: number;
}

const parsedInteractions = computed<ParsedInteraction[]>(() => {
  const out: ParsedInteraction[] = [];
  props.interactions.forEach((inter, idx) => {
    const ms = Date.parse(inter.ts);
    if (!Number.isNaN(ms)) out.push({ inter, idx, ms });
  });
  return out;
});

interface ParsedSegment {
  id: number | string;
  startMs: number;
  endMs: number;
  color: string;
  score: number | null;
}

const parsedSegments = computed<ParsedSegment[]>(() => {
  const out: ParsedSegment[] = [];
  for (const seg of props.routeSegments) {
    const t1 = Date.parse(seg.p1.ts);
    const t2 = Date.parse(seg.p2.ts);
    if (Number.isNaN(t1) || Number.isNaN(t2)) continue;
    out.push({
      id: seg.id,
      startMs: Math.min(t1, t2),
      endMs: Math.max(t1, t2),
      color: scoreToColor(seg.score),
      score: seg.score ?? null,
    });
  }
  return out;
});

const fullRange = computed<Range | null>(() => {
  let min = Infinity;
  let max = -Infinity;
  for (const p of parsedInteractions.value) {
    if (p.ms < min) min = p.ms;
    if (p.ms > max) max = p.ms;
  }
  for (const seg of parsedSegments.value) {
    if (seg.startMs < min) min = seg.startMs;
    if (seg.endMs > max) max = seg.endMs;
  }
  if (min === Infinity || max === -Infinity) return null;
  return { startMs: min, endMs: max };
});

const manualRange = ref<Range | null>(null);
const viewRange = computed<Range | null>(() => manualRange.value ?? fullRange.value);

const isZoomed = computed(() => manualRange.value !== null);

function emitWindowChange() {
  const v = viewRange.value;
  const f = fullRange.value;
  if (!v || !f || (v.startMs === f.startMs && v.endMs === f.endMs)) {
    emit('window-change', null);
  } else {
    emit('window-change', { start: new Date(v.startMs), end: new Date(v.endMs) });
  }
}

interface TimelineEvent {
  inter: InteractionPointView;
  idx: number;
  leftPct: number;
}

const visibleEvents = computed<TimelineEvent[]>(() => {
  const v = viewRange.value;
  if (!v) return [];
  const span = v.endMs - v.startMs;
  if (span <= 0) return [];
  const out: TimelineEvent[] = [];
  for (const p of parsedInteractions.value) {
    if (p.ms < v.startMs || p.ms > v.endMs) continue;
    out.push({ inter: p.inter, idx: p.idx, leftPct: ((p.ms - v.startMs) / span) * 100 });
  }
  return out;
});

interface SegmentBar {
  id: number | string;
  leftPct: number;
  widthPct: number;
  color: string;
  tooltip: string;
}

const segmentBars = computed<SegmentBar[]>(() => {
  const v = viewRange.value;
  const segs = parsedSegments.value;
  if (!v || !segs.length) return [];
  const span = v.endMs - v.startMs;
  if (span <= 0) return [];
  const out: SegmentBar[] = [];
  for (const seg of segs) {
    if (seg.endMs < v.startMs || seg.startMs > v.endMs) continue;
    const clipStart = Math.max(seg.startMs, v.startMs);
    const clipEnd = Math.min(seg.endMs, v.endMs);
    out.push({
      id: seg.id,
      leftPct: ((clipStart - v.startMs) / span) * 100,
      widthPct: Math.max(0.05, ((clipEnd - clipStart) / span) * 100),
      color: seg.color,
      // The Low/High gradient legend is gone (dense layout) — the score
      // rides on the bar's tooltip instead.
      tooltip: seg.score != null ? `Route score: ${Math.round(seg.score)} / 100` : 'Route score: n/a',
    });
  }
  return out;
});

const motionActivityBars = computed(() => {
  const v = viewRange.value;
  if (!v || !props.motionActivitySegments?.length) return [];
  const targetBuckets = Math.max(40, Math.min(200, Math.round((trackWidthPx.value || 800) / 8)));
  const coarsened = coarsenBands(props.motionActivitySegments, v, targetBuckets);
  return buildMotionActivityBars(coarsened, v);
});

// Axis times render in the shift's timezone when provided (same as the
// interaction tables), NOT the UTC-pinned formatters from utils/canvassing/format
// — those stay UTC to match backend-built popup/summary text.
const { timezone: viewerTimezone } = useUserRole();
const axisZone = computed(() => props.timezone || viewerTimezone.value || 'UTC');

const startLabel = computed(() =>
  viewRange.value
    ? formatDateTzToFormat(new Date(viewRange.value.startMs).toISOString(), 'MM/dd, h:mm aaa', axisZone.value)
    : ''
);
const endLabel = computed(() =>
  viewRange.value
    ? formatDateTzToFormat(new Date(viewRange.value.endMs).toISOString(), 'MM/dd, h:mm aaa', axisZone.value)
    : ''
);

const hourTicks = computed<{ ms: number; leftPct: number; label: string }[]>(() => {
  const v = viewRange.value;
  if (!v) return [];
  const span = v.endMs - v.startMs;
  if (span <= 0) return [];

  const HOUR = 60 * 60 * 1000;
  const MIN = 60 * 1000;
  let intervalMs: number;
  if (span > 24 * HOUR) intervalMs = 6 * HOUR;
  else if (span > 12 * HOUR) intervalMs = 4 * HOUR;
  else if (span > 6 * HOUR) intervalMs = 2 * HOUR;
  else if (span > 2 * HOUR) intervalMs = HOUR;
  else if (span > 30 * MIN) intervalMs = 30 * MIN;
  else if (span > 10 * MIN) intervalMs = 5 * MIN;
  else intervalMs = MIN;

  const startTick = Math.ceil(v.startMs / intervalMs) * intervalMs;
  const ticks: { ms: number; leftPct: number; label: string }[] = [];
  for (let t = startTick; t < v.endMs; t += intervalMs) {
    const pct = ((t - v.startMs) / span) * 100;
    if (pct > 6 && pct < 94) {
      ticks.push({
        ms: t,
        leftPct: pct,
        label: formatDateTzToFormat(new Date(t).toISOString(), 'h:mm aaa', axisZone.value),
      });
    }
  }
  return ticks;
});

function isDimmed(inter: InteractionPointView): boolean {
  return props.selectedResponses.length > 0 && !props.selectedResponses.includes(inter.response);
}

const trackRef = useTemplateRef<HTMLElement>('trackRef');
const { width: trackWidthPx } = useElementSize(trackRef);

const MIN_SPAN_MS = 60 * 1000;
const MIN_BRUSH_PX = 6;
const LABEL_MIN_GAP_PX = 15;

const showEventLabels = computed(() => {
  const events = visibleEvents.value;
  if (!events.length) return false;
  if (events.length === 1) return true;
  if (trackWidthPx.value === 0) return false;
  let minGapPx = Infinity;
  for (let i = 1; i < events.length; i++) {
    const gapPx = ((events[i].leftPct - events[i - 1].leftPct) / 100) * trackWidthPx.value;
    if (gapPx < minGapPx) minGapPx = gapPx;
  }
  return minGapPx >= LABEL_MIN_GAP_PX;
});

interface BrushState {
  startX: number;
  currentX: number;
  rectLeft: number;
  rectWidth: number;
  viewAtStart: Range;
}

const brushState = ref<BrushState | null>(null);
let pendingClientX: number | null = null;
let rafHandle: number | null = null;

const brushOverlay = computed<{ leftPct: number; widthPct: number } | null>(() => {
  const b = brushState.value;
  if (!b || b.rectWidth === 0) return null;
  const startPct = ((b.startX - b.rectLeft) / b.rectWidth) * 100;
  const currentPct = ((b.currentX - b.rectLeft) / b.rectWidth) * 100;
  const leftPct = Math.max(0, Math.min(100, Math.min(startPct, currentPct)));
  const rightPct = Math.max(0, Math.min(100, Math.max(startPct, currentPct)));
  const widthPct = rightPct - leftPct;
  if (widthPct < 0.1) return null;
  return { leftPct, widthPct };
});

function onTrackPointerDown(e: PointerEvent) {
  if (!viewRange.value || !trackRef.value) return;
  if ((e.target as HTMLElement).tagName === 'BUTTON') return;
  const rect = trackRef.value.getBoundingClientRect();
  brushState.value = {
    startX: e.clientX,
    currentX: e.clientX,
    rectLeft: rect.left,
    rectWidth: rect.width,
    viewAtStart: { ...viewRange.value },
  };
  (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
}

function onTrackPointerMove(e: PointerEvent) {
  if (!brushState.value) return;
  pendingClientX = e.clientX;
  if (rafHandle === null) {
    rafHandle = requestAnimationFrame(() => {
      rafHandle = null;
      const clientX = pendingClientX;
      pendingClientX = null;
      const b = brushState.value;
      if (clientX === null || !b || !trackRef.value) return;
      const rect = trackRef.value.getBoundingClientRect();
      brushState.value = { ...b, currentX: clientX, rectLeft: rect.left, rectWidth: rect.width };
    });
  }
}

function onTrackPointerUp(e: PointerEvent) {
  const target = e.currentTarget as HTMLElement | null;
  if (target?.hasPointerCapture(e.pointerId)) target.releasePointerCapture(e.pointerId);

  const b = brushState.value;
  if (!b) return;
  brushState.value = null;
  pendingClientX = null;
  if (rafHandle !== null) {
    cancelAnimationFrame(rafHandle);
    rafHandle = null;
  }

  if (b.rectWidth === 0) return;
  if (Math.abs(b.currentX - b.startX) < MIN_BRUSH_PX) return;

  const startPct = (Math.min(b.startX, b.currentX) - b.rectLeft) / b.rectWidth;
  const endPct = (Math.max(b.startX, b.currentX) - b.rectLeft) / b.rectWidth;
  const v = b.viewAtStart;
  const span = v.endMs - v.startMs;
  let newStart = v.startMs + span * Math.max(0, Math.min(1, startPct));
  let newEnd = v.startMs + span * Math.max(0, Math.min(1, endPct));
  if (newEnd - newStart < MIN_SPAN_MS) {
    const mid = (newStart + newEnd) / 2;
    newStart = mid - MIN_SPAN_MS / 2;
    newEnd = mid + MIN_SPAN_MS / 2;
  }
  const f = fullRange.value;
  if (!f) return;
  manualRange.value = { startMs: Math.max(newStart, f.startMs), endMs: Math.min(newEnd, f.endMs) };
  emitWindowChange();
}

function resetView() {
  manualRange.value = null;
  emitWindowChange();
}
</script>
