const RESPONSE_TO_UNIFIED_BY_APP: Partial<Record<CanvassingApplicationName, RawResponseMap>> = {
  numinar: NUMINAR_RESPONSE_TO_UNIFIED,
  advantage: ADVANTAGE_RESPONSE_TO_UNIFIED,
  i360: I360_RESPONSE_TO_UNIFIED,
};

// Unknown raw responses (and apps without a mapping) resolve to `none`, mirroring
// the backend aggregator `_response_to_unified`. Returning `null` for a missing
// raw value keeps callers like the row dot from rendering a swatch when there
// is nothing to show.
export function getUnifiedResponse(
  rawResponse: string | null | undefined,
  app: CanvassingApplicationName
): UnifiedResponseTypeEnum | null {
  if (!rawResponse) return null;
  const mapping = RESPONSE_TO_UNIFIED_BY_APP[app];
  if (!mapping) return 'none';
  return mapping[rawResponse] ?? 'none';
}

export function getResponseColor(
  rawResponse: string | null | undefined,
  app: CanvassingApplicationName
): string | null {
  const unified = getUnifiedResponse(rawResponse, app);
  if (unified === null) return null;
  return RESPONSE_TYPE_COLOR[unified] ?? RESPONSE_TYPE_COLOR.none;
}

