export function formatStatsKpiValue(raw: number | null | undefined, unit: StatsKpiUnit): string {
  if (raw === null || raw === undefined || !Number.isFinite(raw)) return EMPTY;

  switch (unit) {
    case 'fraction':
      return `${(raw * 100).toFixed(1)}%`;
    case 'hours':
      return `${raw.toFixed(1)} h`;
    case 'minutes':
      return `${raw.toFixed(0)} min`;
    case 'rate':
      return `${raw.toFixed(2)} /h`;
  }
}

// "0s" / "<1s" / "33s" / "1m 30s" / "1h" / "1h 32m 33s" — compact duration. Used
// for per-row time spans stored in minutes (time_btwn_min). Zero units are
// dropped so "60 min" reads as "1h", not "1h 0m 0s". Sub-second positives are
// rendered as "<1s" so they're not visually confused with a true zero.
export function formatStatsRowDuration(rawMin: number | null | undefined): string {
  if (rawMin === null || rawMin === undefined || !Number.isFinite(rawMin) || rawMin < 0) return EMPTY;
  if (rawMin === 0) return '0s';
  const totalSeconds = Math.round(rawMin * 60);
  if (totalSeconds === 0) return '<1s';
  const h = Math.floor(totalSeconds / 3600);
  const m = Math.floor((totalSeconds % 3600) / 60);
  const s = totalSeconds % 60;
  const parts: string[] = [];
  if (h > 0) parts.push(`${h}h`);
  if (m > 0) parts.push(`${m}m`);
  if (s > 0) parts.push(`${s}s`);
  return parts.join(' ');
}

// "18:55:32" — 24-hour clock with seconds, local timezone. Used for the Time
// column in the per-row interaction log.
export function formatStatsRowClockTime(iso: string | null | undefined): string {
  if (!iso) return EMPTY;
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return EMPTY;
  const h = String(d.getHours()).padStart(2, '0');
  const m = String(d.getMinutes()).padStart(2, '0');
  const s = String(d.getSeconds()).padStart(2, '0');
  return `${h}:${m}:${s}`;
}

export function formatStatsRowFeet(raw: number | null | undefined): string {
  if (raw === null || raw === undefined || !Number.isFinite(raw)) return EMPTY;
  return `${raw.toFixed(0)} ft`;
}

export function formatStatsRowSpeed(raw: number | null | undefined): string {
  if (raw === null || raw === undefined || !Number.isFinite(raw)) return EMPTY;
  return `${raw.toFixed(2)} ft/s`;
}

// Row-severity thresholds mirror the backend scoring buckets (PROX_RANGES_FT /
// SPEED_RANGES in aggregator.py).
export type RowSeverity = 'normal' | 'notable' | 'warning' | 'suspicious';

export function classifyDistFromSeverity(raw: number | null | undefined): RowSeverity {
  if (raw === null || raw === undefined || !Number.isFinite(raw)) return 'normal';
  if (raw < 200) return 'normal';
  if (raw < 500) return 'notable';
  if (raw < 1000) return 'warning';
  return 'suspicious';
}

export function classifyWalkingSpeedSeverity(raw: number | null | undefined): RowSeverity {
  if (raw === null || raw === undefined || !Number.isFinite(raw)) return 'normal';
  if (raw === 0) return 'normal';
  if (raw > 10) return 'suspicious';
  if (raw > 6 || raw < 0.9) return 'warning';
  return 'normal';
}

export const ROW_SEVERITY_CLASS: Record<RowSeverity, string> = {
  normal: '',
  notable: 'text-yellow-600 dark:text-yellow-500 font-semibold',
  warning: 'text-orange-600 dark:text-orange-500 font-semibold',
  suspicious: 'text-red-600 dark:text-red-500 font-semibold',
};

// Background tints overlay the text colors above. The four-tier severity is
// rolled up into three buckets (green / yellow / red) so the table matches the
// filter chips at the top of WorkshiftStatisticsRowsTable.
export const ROW_SEVERITY_BG_CLASS: Record<RowSeverity, string> = {
  normal: 'bg-green-100 dark:bg-green-900/30',
  notable: 'bg-yellow-100 dark:bg-yellow-900/30',
  warning: 'bg-yellow-100 dark:bg-yellow-900/30',
  suspicious: 'bg-red-100 dark:bg-red-900/30',
};

// A "filter bucket" is the three-color rollup used by the suspiciousness chips
// (yellow/red) and the cell background tints. Rows or cells with no usable
// signal land in `none` and stay untinted, so the table doesn't paint every
// blank cell green.
export type RowConcernBucket = 'none' | 'green' | 'yellow' | 'red';

function severityToBucket(severity: RowSeverity): Exclude<RowConcernBucket, 'none'> {
  if (severity === 'suspicious') return 'red';
  if (severity === 'notable' || severity === 'warning') return 'yellow';
  return 'green';
}

// Cells without a numeric reading (null/undefined/NaN) — and the walking-speed
// "Same House" sentinel of 0 — render untinted. Otherwise we color the cell by
// its severity bucket so the table at a glance shows where data drifts from
// the canvasser's reported house.
export function classifyDistFromBucket(raw: number | null | undefined): RowConcernBucket {
  if (raw === null || raw === undefined || !Number.isFinite(raw)) return 'none';
  return severityToBucket(classifyDistFromSeverity(raw));
}

export function classifyWalkingSpeedBucket(raw: number | null | undefined): RowConcernBucket {
  if (raw === null || raw === undefined || !Number.isFinite(raw)) return 'none';
  if (raw === 0) return 'none';
  return severityToBucket(classifyWalkingSpeedSeverity(raw));
}

// Worst-of the row's tinted cells (red > yellow > green; none if untinted).
export function classifyRowConcern(row: CanvassingAppInteractionRow): RowConcernBucket {
  const buckets: RowConcernBucket[] = [
    classifyDistFromBucket(row.dist_from_ft),
    classifyWalkingSpeedBucket(row.walking_speed_fps),
  ];
  if (buckets.includes('red')) return 'red';
  if (buckets.includes('yellow')) return 'yellow';
  if (buckets.includes('green')) return 'green';
  return 'none';
}

// Score severity (higher = better, opposite of the row metrics above); null when
// the score is unavailable so callers render a neutral card.
export type ScoreSeverity = 'good' | 'warning' | 'poor';

export function classifyScoreSeverity(fraction: number | null | undefined): ScoreSeverity | null {
  if (fraction === null || fraction === undefined || !Number.isFinite(fraction)) return null;
  if (fraction >= 0.7) return 'good';
  if (fraction >= 0.4) return 'warning';
  return 'poor';
}

