// Per-row flag → compact chip label, in display order. Single source of truth
// for the per-row flags; rowFlagLabel derives from it.
export type RowFlagKey = keyof Pick<
  CanvassingAppInteractionRow,
  'is_rapid_response' | 'is_impossible_speed' | 'is_off_site_gps' | 'is_stationary_device' | 'is_out_of_hours'
>;

export const ROW_FLAG_REASONS: ReadonlyArray<{ key: RowFlagKey; label: string }> = [
  { key: 'is_rapid_response', label: 'Rapid Response' },
  { key: 'is_impossible_speed', label: 'Impossible Speed' },
  { key: 'is_off_site_gps', label: 'Off-site GPS' },
  { key: 'is_stationary_device', label: 'Stationary Device' },
  { key: 'is_out_of_hours', label: 'Out of Hours' },
];

// Compact label for a single per-row flag key (e.g. the active drill-down).
export function rowFlagLabel(key: RowFlagKey): string {
  return ROW_FLAG_REASONS.find((r) => r.key === key)?.label ?? key;
}

export function interactionMatchesAppFlag(inter: InteractionPointView, flagFilter: RowFlagKey | null): boolean {
  if (flagFilter === null) return true;
  return (inter.app_flag_reasons ?? []).includes(rowFlagLabel(flagFilter));
}

const STREAK_RESPONSE_LABEL: Partial<Record<UnifiedResponseTypeEnum, string>> = {
  take_survey: 'Survey',
  not_home: 'No Answer',
};

export type StreakSeverity = ResponseStreak['severity'];

// Streak-severity badge styling (status-config pattern, per frontend CLAUDE.md).
// Shared by the streaks table and the flags chips so the two surfaces can't
// drift; dark shades match RISK_LEVEL_CONFIG's high/low badges.
export const STREAK_SEVERITY_BADGE_CLASS: Record<StreakSeverity, string> = {
  high: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300',
  medium: 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-300',
};

// Shared styling for the per-interaction app-flag reason chips (the red reason
// pills on the map popup, the streak member list, and the flagged-interactions
// list). One source so the three surfaces can't drift.
export const APP_FLAG_REASON_CHIP_CLASS =
  'rounded border border-red-400 bg-red-50 px-1.5 py-0.5 text-[10px] font-semibold text-red-800 dark:bg-red-950/40 dark:text-red-200';

// "Survey ×6 (HIGH)" — compact label for a response streak chip.
export function formatResponseStreak(streak: ResponseStreak): string {
  const label = STREAK_RESPONSE_LABEL[streak.response] ?? streak.response;
  return `${label} ×${streak.length} (${streak.severity.toUpperCase()})`;
}

// Flattened streak row for the table: response streaks and flag streaks (rapid /
// stationary) in one shape. `response` / `flagLabel` (exactly one non-null) is the
// predicate streakMemberInteractions matches members on.
export interface StreakRow {
  type: string;
  length: number;
  severity: ResponseStreak['severity'];
  startTime: string | null;
  startAddress: string | null;
  endTime: string | null;
  response: UnifiedResponseTypeEnum | null;
  flagLabel: string | null;
}

export function buildStreakRows(flags: CanvassingAppFlags): StreakRow[] {
  const rows: StreakRow[] = [];
  const push = (
    type: string,
    s: ResponseStreak | FlagStreak,
    member: Pick<StreakRow, 'response' | 'flagLabel'>
  ): void => {
    rows.push({
      type,
      length: s.length,
      severity: s.severity,
      startTime: s.start_time ?? null,
      startAddress: s.start_address ?? null,
      endTime: s.end_time ?? null,
      ...member,
    });
  };
  for (const s of flags.no_answer_streaks ?? []) push('No Answer', s, { response: s.response, flagLabel: null });
  for (const s of flags.survey_streaks ?? []) push('Survey', s, { response: s.response, flagLabel: null });
  for (const s of flags.rapid_response_streaks ?? [])
    push('Rapid Response', s, { response: null, flagLabel: rowFlagLabel('is_rapid_response') });
  for (const s of flags.stationary_clusters ?? [])
    push('Stationary Device', s, { response: null, flagLabel: rowFlagLabel('is_stationary_device') });
  return rows;
}

// Recover a streak's member interactions by time window + response/flag-label
// predicate (not by index). See the canvassing-app-fraud-flags doc for why.
export function streakMemberInteractions(
  streak: StreakRow,
  interactions: InteractionPointView[]
): InteractionPointView[] {
  const start = streak.startTime ? Date.parse(streak.startTime) : null;
  const end = streak.endTime ? Date.parse(streak.endTime) : null;
  return interactions.filter((i) => {
    const t = Date.parse(i.ts);
    if (Number.isNaN(t)) return false;
    if (start !== null && t < start) return false;
    if (end !== null && t > end) return false;
    if (streak.response !== null) return i.response === streak.response;
    if (streak.flagLabel !== null) return (i.app_flag_reasons ?? []).includes(streak.flagLabel);
    return true;
  });
}

