// Neutral styling for a risk level the client doesn't know yet (backend may add
// one) so a raw lookup can't return undefined and break `.label` / `.badgeClass`
// access. The label is filled from the value by the getter below.
const defaultRiskLevel: { label: string; badgeClass: string; borderClass: string } = {
  label: '',
  badgeClass: 'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-300',
  borderClass: 'border-l-gray-500',
};

export function getRiskLevel(level: RiskLevel): { label: string; badgeClass: string; borderClass: string } {
  return RISK_LEVEL_CONFIG[level] ?? { ...defaultRiskLevel, label: snakeCaseToCapitalizedCase(level) };
}

