export type FraudSeverity = 'normal' | 'notable' | 'concerning' | 'critical';

export interface FraudSeverityStyle {
  label: string;
  chipClass: string;
  borderClass: string;
  bulletBgClass: string;
  bulletTextClass: string;
  /** Tailwind solid-fill class for accent dots in lists/popups. */
  dotBgClass: string;
  /** Hex code for non-Tailwind consumers (e.g. Google Maps marker stroke). */
  mapRingHex: string;
  rank: number;
}

