export function getFraudSeverityStyle(severity: FraudSeverity | string | null | undefined): FraudSeverityStyle {
  if (severity && severity in fraudSeverityConfig) {
    return fraudSeverityConfig[severity as FraudSeverity];
  }
  return fraudSeverityConfig.normal;
}

export const ANOMALY_BAR_NORMAL_PCT = 2;
export const ANOMALY_BAR_CRITICAL_PCT = 15;

// Flagged = sensor scorer (counts_as_suspect) OR canvassing-app flags (app_flag_reasons).
// Docs: docs/specs/reports-and-fraud/canvassing-app-fraud-flags.md#report-page-surfaces
export function isFlaggedInteraction(interaction: InteractionPointView): boolean {
  return interaction.counts_as_suspect === true || (interaction.app_flag_reasons?.length ?? 0) > 0;
}

export interface FraudAnomalyBar {
  title: string;
  description: string;
  value: number;
}

export interface FraudCardExtra {
  label: string;
  value: string;
}

export interface FraudSpeedGauge {
  avg: number;
  top: number;
}

export type FraudReportCardKey = ReportCardClassification['key'];

export interface FraudReportCardData {
  key: FraudReportCardKey;
  title: string;
  icon: Component;
  severity: FraudSeverity;
  headline: string;
  subtitle: string;
  anomalyBars?: FraudAnomalyBar[];
  extras?: FraudCardExtra[];
  speedGauge?: FraudSpeedGauge;
  flaggedInteractions?: InteractionPointView[];
}

const MPS_TO_MPH = 2.2369362920544;

function paceLabel(mps: number): string {
  if (mps < 0.4) return 'still';
  if (mps < 2.0) return 'walking pace';
  if (mps < 3.5) return 'jogging pace';
  if (mps < 5.5) return 'running pace';
  if (mps < 8.5) return 'cycling pace';
  return 'vehicle pace';
}

// Pace summary that collapses to one phrase when average and peak land in the
// same bucket — avoids reading like "average vehicle pace, peaks at vehicle pace".
function pacePhrase(avgMps: number, topMps: number): string {
  const avgLabel = paceLabel(avgMps);
  const topLabel = paceLabel(topMps);
  if (avgLabel === topLabel) {
    return avgLabel === 'still' ? 'Barely moving throughout.' : `Around ${avgLabel} throughout.`;
  }
  return `Average ${avgLabel}, peaks at ${topLabel}.`;
}

const PHONE_ANOMALY_COPY: Array<{ magnitudeKey: string; title: string; description: string }> = [
  {
    magnitudeKey: 'moved_but_low_motion_pct',
    title: 'GPS moved while the phone was still',
    description:
      'GPS coordinates advanced but the accelerometer / gyroscope stayed nearly idle. Typical for a phone in a vehicle or for a spoofed location feed.',
  },
  {
    magnitudeKey: 'stationary_but_high_motion_pct',
    title: 'Phone moved while GPS was frozen',
    description:
      'Motion sensors picked up activity but the GPS did not advance. Often indicates a phone being shaken in place to fake walking.',
  },
  {
    magnitudeKey: 'fast_spinning_pct',
    title: 'Unnatural rotation',
    description:
      'The gyroscope registered angular velocity faster than realistic for normal walking. Suggests the device was spun, rolled, or manipulated.',
  },
  {
    magnitudeKey: 'high_acceleration_pct',
    title: 'Impossible acceleration bursts',
    description:
      'Linear acceleration exceeded what a human normally produces while walking. Suggests the device was in a vehicle or being tossed.',
  },
];

interface CardRenderResult {
  headline: string;
  subtitle: string;
  anomalyBars?: FraudAnomalyBar[];
  extras?: FraudCardExtra[];
  speedGauge?: FraudSpeedGauge;
  flaggedInteractions?: InteractionPointView[];
}

interface CardRender {
  title: string;
  icon: Component;
  build: (
    cls: ReportCardClassification,
    stats: RenderedReport,
    interactions?: InteractionPointView[]
  ) => CardRenderResult;
}

function mag(cls: ReportCardClassification, key: string): number {
  const m = cls.magnitudes ?? {};
  const v = m[key];
  return typeof v === 'number' && !Number.isNaN(v) ? v : 0;
}

function magOrNull(cls: ReportCardClassification, key: string): number | null {
  const m = cls.magnitudes ?? {};
  const v = m[key];
  return typeof v === 'number' && !Number.isNaN(v) ? v : null;
}

const CARD_RENDER: Record<FraudReportCardKey, CardRender> = {
  movement: {
    title: 'Movement',
    icon: FootprintsIcon,
    build: (cls) => {
      const avg = mag(cls, 'avg_speed_mps');
      const top = mag(cls, 'top_speed_mps');
      const mismatch = magOrNull(cls, 'speed_mismatch_pct');
      const headline = `${avg.toFixed(1)} m/s avg · ${top.toFixed(1)} m/s top (≈${(top * MPS_TO_MPH).toFixed(0)} mph)`;
      // `speed_mismatch_pct`: the phone's self-reported speed vs. the speed calculated from its
      // GPS track (see the speed tiles in fraudKpiConfig.ts). Both are GPS-derived — this is NOT
      // the accelerometer/gyro vs GPS check, which is the Phone Behavior card.
      const disagreed = (pct: number): string =>
        `The phone's reported speed didn't match the speed calculated from its GPS track in ${pct.toFixed(0)}% of the route`;
      let subtitle: string;
      if (mismatch === null) {
        subtitle = `${pacePhrase(avg, top)} Speed comparison unavailable.`;
      } else if (cls.severity === 'critical') {
        subtitle = `${disagreed(mismatch)} — a strong outlier.`;
      } else if (cls.severity === 'concerning') {
        subtitle = `${disagreed(mismatch)}.`;
      } else if (cls.severity === 'notable') {
        subtitle = `${disagreed(mismatch)}. ${pacePhrase(avg, top)}`;
      } else {
        subtitle = `${pacePhrase(avg, top)} Reported and calculated speed agree.`;
      }
      return { headline, subtitle, speedGauge: { avg, top } };
    },
  },
  engagement: {
    title: 'Engagement',
    icon: MessageSquareIcon,
    build: (cls, _stats, interactions) => {
      const total = mag(cls, 'total_interactions');
      const noGps = mag(cls, 'interactions_without_gps');
      const noGpsPct = mag(cls, 'interactions_without_gps_pct');
      const medianDurRaw = cls.magnitudes?.median_duration_s;
      const hasMedian = typeof medianDurRaw === 'number' && !Number.isNaN(medianDurRaw);
      const durLabel = hasMedian ? `Median ${formatSecondsHuman(medianDurRaw as number)}` : 'Median duration n/a';

      const flaggedInteractions = interactions ? interactions.filter(isFlaggedInteraction) : undefined;
      let suspected: number;
      let flaggedPct: number;
      if (flaggedInteractions) {
        suspected = flaggedInteractions.length;
        flaggedPct = total > 0 ? Math.min(100, (suspected / total) * 100) : 0;
      } else {
        suspected = mag(cls, 'suspected_interactions');
        flaggedPct = mag(cls, 'suspected_pct');
      }

      const headline =
        total > 0
          ? `${total.toFixed(0)} interactions · ${suspected.toFixed(0)} flagged (${flaggedPct.toFixed(0)}%)`
          : 'No interactions logged';

      const noGpsLine = noGps > 0 ? ` ${noGps.toFixed(0)} (${noGpsPct.toFixed(0)}%) logged without GPS evidence.` : '';

      let subtitle: string;
      if (total === 0) {
        // No interactions at all — don't say "X% of interactions look suspicious".
        subtitle = noGps > 0 ? `${noGps.toFixed(0)} interactions had no GPS evidence.` : 'No interactions to evaluate.';
      } else if (cls.severity === 'critical' || cls.severity === 'concerning') {
        subtitle = `${flaggedPct.toFixed(0)}% of interactions look suspicious. ${durLabel}.${noGpsLine}`;
      } else if (cls.severity === 'notable') {
        if (noGps > 0) {
          subtitle = `${noGps.toFixed(0)} interaction(s) had no GPS evidence (${noGpsPct.toFixed(0)}% of total).`;
        } else if (hasMedian && (medianDurRaw as number) < 10) {
          subtitle = `Median interaction lasts only ${formatSecondsHuman(medianDurRaw as number)} — unusually short.`;
        } else {
          subtitle = `${suspected.toFixed(0)} flagged interaction${suspected === 1 ? '' : 's'}. ${durLabel}.`;
        }
      } else {
        subtitle = `${durLabel} — typical for canvassing.`;
      }
      return { headline, subtitle, flaggedInteractions };
    },
  },
  phone_behaviour: {
    title: 'Phone Behavior',
    icon: SmartphoneIcon,
    build: (cls) => {
      const tripped = mag(cls, 'tripped_count');
      const headline =
        tripped === 0
          ? 'All anomaly types within normal range'
          : `${tripped.toFixed(0)} of ${PHONE_ANOMALY_COPY.length} anomaly types rised signals outside normal patterns`;
      const subtitle =
        cls.severity === 'normal'
          ? 'Phone sensors agree with GPS movement throughout.'
          : 'Each bar below shows the share of the shift where the signal was abnormal.';
      const anomalyBars: FraudAnomalyBar[] = PHONE_ANOMALY_COPY.map((c) => ({
        title: c.title,
        description: c.description,
        value: mag(cls, c.magnitudeKey),
      }));
      return { headline, subtitle, anomalyBars };
    },
  },
  gps_quality: {
    title: 'GPS Quality',
    icon: MapPinIcon,
    build: (cls) => {
      const simulated = mag(cls, 'simulated') === 1;
      const coverage = magOrNull(cls, 'coverage_pct');
      const untracked = magOrNull(cls, 'untracked_pct');
      const headline = simulated
        ? 'Spoofed location detected'
        : coverage !== null
          ? `${coverage.toFixed(0)}% of the shift was tracked`
          : 'GPS coverage data unavailable';
      let subtitle: string;
      if (simulated) {
        subtitle = 'The GPS feed shows signs of being faked.';
      } else if (coverage === null) {
        subtitle = 'No GPS samples were recorded for this shift.';
      } else if (cls.severity === 'concerning') {
        subtitle = `Only ${coverage.toFixed(0)}% of the shift had GPS coverage — large untracked gaps.`;
      } else if (cls.severity === 'notable') {
        const untrackedTxt = untracked !== null ? `${untracked.toFixed(0)}% of the shift untracked` : 'gaps detected';
        subtitle = `Some GPS gaps (${untrackedTxt}).`;
      } else if (cls.severity === 'critical') {
        subtitle = `GPS coverage is very poor, with ${untracked?.toFixed(0) ?? 'many'} untracked gaps.`;
      } else {
        subtitle = 'GPS feed looks real and consistent.';
      }
      return { headline, subtitle };
    },
  },
  surroundings: {
    title: 'Surroundings',
    icon: WifiIcon,
    build: (cls, stats) => {
      const ble = mag(cls, 'ble_unique');
      const wifi = mag(cls, 'wifi_unique');
      const shiftLen = mag(cls, 'shift_length_s');
      const isLongShift = shiftLen > 3600;

      const headline = `${ble.toFixed(0)} BLE · ${wifi.toFixed(0)} Wi-Fi devices`;
      let subtitle: string;
      if (cls.severity === 'notable' && isLongShift && ble < 5 && wifi < 5) {
        subtitle = 'Very few nearby devices for a long shift — limited movement through environments.';
      } else if (cls.severity === 'notable') {
        subtitle = 'Unusually high device diversity — passed through many environments.';
      } else {
        subtitle = 'Stable nearby-device picture — typical for canvassing.';
      }

      const extras: FraudCardExtra[] = [];
      if (stats.most_common_ble_device) extras.push({ label: 'Top BLE', value: stats.most_common_ble_device });
      if (stats.most_common_wifi_device) extras.push({ label: 'Top Wi-Fi', value: stats.most_common_wifi_device });

      return { headline, subtitle, extras: extras.length ? extras : undefined };
    },
  },
  shift_integrity: {
    title: 'Shift Integrity',
    icon: ClockIcon,
    build: (cls) => {
      const shiftLen = mag(cls, 'shift_length_s');
      const pauseSec = mag(cls, 'total_pause_seconds');
      const pauseRatio = mag(cls, 'pause_ratio_pct');
      const numPauses = mag(cls, 'num_pauses');

      const headline =
        shiftLen > 0
          ? `${formatSecondsHuman(shiftLen)} total · ${numPauses.toFixed(0)} pause${numPauses === 1 ? '' : 's'}`
          : 'No shift data';
      let subtitle: string;
      if (cls.severity === 'concerning') {
        subtitle = `Spent ${pauseRatio.toFixed(0)}% of the shift on pause across ${numPauses.toFixed(0)} pauses.`;
      } else if (cls.severity === 'notable') {
        subtitle = `${numPauses.toFixed(0)} pauses totalling ${formatSecondsHuman(pauseSec)} (${pauseRatio.toFixed(0)}% of shift).`;
      } else {
        subtitle =
          numPauses > 0
            ? `${numPauses.toFixed(0)} pauses totalling ${formatSecondsHuman(pauseSec)} — within normal range.`
            : 'No pauses logged during the shift.';
      }

      const extras: FraudCardExtra[] = [];
      if (numPauses > 0)
        extras.push({ label: 'Pauses', value: `${numPauses.toFixed(0)} · ${formatSecondsHuman(pauseSec)}` });

      return { headline, subtitle, extras: extras.length ? extras : undefined };
    },
  },
  canvassing_app: {
    title: 'Canvassing App',
    icon: SmartphoneIcon,
    build: (cls, stats) => {
      const flags = stats.app_flags ?? null;
      const impossibleSpeed = mag(cls, 'impossible_speed');
      const rapid = mag(cls, 'rapid_response');
      const offSite = mag(cls, 'off_site_gps');
      const stationary = mag(cls, 'stationary_device');
      const parts: string[] = [];
      if (impossibleSpeed > 0) parts.push(`${impossibleSpeed.toFixed(0)} impossible-speed jumps`);
      if (rapid > 0) parts.push(`${rapid.toFixed(0)} rapid response`);
      if (offSite > 0) parts.push(`${offSite.toFixed(0)} off-site GPS`);
      if (stationary > 0) parts.push(`${stationary.toFixed(0)} stationary device`);
      const headline = parts.length ? parts.join(' · ') : 'No canvassing-app flags detected.';
      const subtitle =
        flags?.risk_reasons?.[0]?.text ??
        (flags?.device_did_not_move
          ? 'Device GPS barely moved across the whole shift.'
          : 'Behavioral flags from the canvassing app.');
      return { headline, subtitle };
    },
  },
};

const CARD_ORDER: FraudReportCardKey[] = [
  'engagement',
  'movement',
  'phone_behaviour',
  'gps_quality',
  'surroundings',
  'shift_integrity',
];

// Card layout rule:
//   1. Engagement — pinned first because flagged interactions are the primary
//      surface for this report (the "Top concerns" summary sits above and
//      already surfaces the highest-severity signal independently).
//   2. Remaining middle cards — sorted by severity DESC, then CARD_ORDER.
//   3. Movement — pinned last (least informative dimension for ops review).
export function arrangeCards(cards: FraudReportCardData[]): FraudReportCardData[] {
  const byKey = new Map(cards.map((c) => [c.key, c] as const));
  const pickByKey = (key: FraudReportCardKey): FraudReportCardData | undefined => {
    const c = byKey.get(key);
    if (c) byKey.delete(key);
    return c;
  };

  const orderIndex = (key: FraudReportCardKey): number => CARD_ORDER.indexOf(key);
  const bySeverityThenOrder = (a: FraudReportCardData, b: FraudReportCardData): number => {
    const dr = fraudSeverityConfig[b.severity].rank - fraudSeverityConfig[a.severity].rank;
    return dr !== 0 ? dr : orderIndex(a.key) - orderIndex(b.key);
  };

  const engagement = pickByKey('engagement');
  const movement = pickByKey('movement');
  const middle = [...byKey.values()].sort(bySeverityThenOrder);

  return [engagement, ...middle, movement].filter((c): c is FraudReportCardData => c !== undefined);
}

const FALLBACK_HEADLINE = 'Classification unavailable';
const FALLBACK_SUBTITLE = 'Generated before classification was available — regenerate this report to see severity.';

function fallbackCards(): FraudReportCardData[] {
  return CARD_ORDER.map((key) => ({
    key,
    title: CARD_RENDER[key].title,
    icon: CARD_RENDER[key].icon,
    severity: 'normal' as FraudSeverity,
    headline: FALLBACK_HEADLINE,
    subtitle: FALLBACK_SUBTITLE,
  }));
}

export function buildReportCards(stats: RenderedReport, interactions?: InteractionPointView[]): FraudReportCardData[] {
  const classifications = stats.report_cards;
  if (!classifications || classifications.length === 0) return arrangeCards(fallbackCards());

  const byKey = new Map<FraudReportCardKey, ReportCardClassification>();
  for (const cls of classifications) byKey.set(cls.key, cls);

  const cards = CARD_ORDER.map((key) => {
    const cls = byKey.get(key);
    const render = CARD_RENDER[key];
    if (!cls) {
      return {
        key,
        title: render.title,
        icon: render.icon,
        severity: 'normal' as FraudSeverity,
        headline: FALLBACK_HEADLINE,
        subtitle: FALLBACK_SUBTITLE,
      };
    }
    const built = render.build(cls, stats, interactions);
    return {
      key,
      title: render.title,
      icon: render.icon,
      severity: cls.severity,
      ...built,
    };
  });
  return arrangeCards(cards);
}
