// Color curve for route-segment fraud scores in [0, 100].
// Hue runs from blue (low) → magenta → red (high); slight darkening at the high end.
export function scoreToColor(score: number): string {
  const c = Math.max(0, Math.min(100, score)) / 100;
  const hue = (220 + 140 * c) % 360;
  const sat = 70;
  const light = 50 - c * 5;
  return `hsl(${hue.toFixed(1)}, ${sat}%, ${light.toFixed(1)}%)`;
}

// 5-stop CSS linear-gradient matching the scoreToColor curve.
export function scoreGradientCss(): string {
  const stops = [0, 25, 50, 75, 100].map((s) => `${scoreToColor(s)} ${s}%`).join(', ');
  return `linear-gradient(to right, ${stops})`;
}
