<template>
  <div class="flex flex-col gap-3">
    <div v-if="pauseMarkers.length" class="flex flex-wrap items-center gap-x-6 gap-y-2 text-sm">
      <label class="flex items-center gap-2 cursor-pointer">
        <input v-model="showPauses" type="checkbox" class="h-4 w-4" />
        <span>Pauses ({{ pauseMarkers.length.toLocaleString() }})</span>
      </label>
    </div>

    <div
      v-if="showLegend && interactionLegend.length"
      class="flex flex-wrap items-center gap-x-2 gap-y-2 text-base text-muted-foreground"
    >
      <button
        v-for="entry in interactionLegend"
        :key="entry.response"
        type="button"
        :aria-pressed="selectedResponseSet.has(entry.response)"
        :class="[
          'flex items-center gap-2 rounded-md px-3 py-1.5 transition-opacity transition-colors',
          'hover:bg-muted/60',
          selectedResponseSet.has(entry.response) ? 'bg-muted text-foreground ring-1 ring-foreground/20' : '',
          selectedResponses.length > 0 && !selectedResponseSet.has(entry.response) ? 'opacity-40' : '',
        ]"
        @click="toggleSelectedResponse(entry.response)"
      >
        <span
          class="inline-block h-3.5 w-3.5 rounded-full border border-white shadow-[0_0_0_1px_rgba(0,0,0,0.05)]"
          :style="{ backgroundColor: entry.color }"
        />
        <span>{{ entry.label }}</span>
        <span class="text-sm tabular-nums text-muted-foreground/80">{{ entry.count.toLocaleString() }}</span>
      </button>
      <span class="ml-auto text-base text-foreground">
        Total: <span class="font-semibold tabular-nums">{{ totalInteractions.toLocaleString() }}</span>
      </span>
    </div>

    <div class="relative w-full rounded-md overflow-hidden border" :class="heightClass">
      <GoogleMap
        ref="mapRef"
        :api-key="apiKey"
        :center="initialCenter"
        :zoom="initialZoom"
        :max-zoom="22"
        :min-zoom="3"
        :clickable-icons="false"
        style="width: 100%; height: 100%"
        @zoom_changed="onZoomChange"
      >
        <Polyline v-for="(gap, index) in gapConnectors" :key="`gap-${index}`" :options="gap" />

        <Polyline
          v-for="seg in segmentPolylines"
          :key="`seg-${seg.id}`"
          :options="seg.options"
          @click="onSegmentClick(seg, $event)"
        />

        <Polyline
          v-for="(run, idx) in directionRuns"
          :key="`arrow-${idx}`"
          :options="{
            path: run,
            geodesic: false,
            strokeOpacity: 0,
            strokeWeight: 0,
            zIndex: 3,
            icons: arrowIcons,
          }"
        />

        <Polyline
          v-if="interactionTrailPath.length >= 2"
          :options="{
            path: interactionTrailPath,
            geodesic: false,
            strokeColor: '#6b7280',
            strokeOpacity: 0.8,
            strokeWeight: 2,
            zIndex: 0,
          }"
        />

        <Marker
          v-for="(opts, idx) in interactionMarkerOptionsList"
          :key="`int-${idx}`"
          :options="opts"
          @click="toggleInteractionPopup(validInteractions[idx], idx)"
        />

        <Polyline v-for="i in canvasserPins" :key="`cgap-${i.id}`" :options="canvasserGapLineOptions(i)" />

        <CustomMarker
          v-for="i in canvasserPins"
          :key="`cpin-${i.id}`"
          :options="{ position: { lat: i.canvasser_lat, lng: i.canvasser_lon }, anchorPoint: 'BOTTOM_CENTER' }"
        >
          <button type="button" class="flex cursor-pointer flex-col items-center" @click="onCanvasserPinClick(i)">
            <span
              class="flex h-6 w-6 items-center justify-center rounded-full border-2 border-white shadow-md"
              :style="{ backgroundColor: canvasserPinHex(i) }"
            >
              <svg viewBox="0 0 24 24" class="h-3.5 w-3.5 fill-white"><path :d="PERSON_PATH" /></svg>
            </span>
            <span
              class="-mt-1 h-2 w-2 rotate-45 border-b-2 border-r-2 border-white"
              :style="{ backgroundColor: canvasserPinHex(i) }"
            />
          </button>
        </CustomMarker>

        <CustomMarker
          v-for="i in canvasserPins"
          :key="`cdist-${i.id}`"
          :options="{ position: canvasserMidpoint(i), anchorPoint: 'CENTER' }"
        >
          <span
            class="rounded-full bg-white/90 px-1.5 py-0.5 text-[10px] font-semibold text-gray-800 shadow ring-1 ring-black/10 whitespace-nowrap"
          >
            {{ formatGap(i) }}
          </span>
        </CustomMarker>

        <Marker v-if="startFlagMarkerOptions" :options="startFlagMarkerOptions" />
        <Marker v-if="endFlagMarkerOptions" :options="endFlagMarkerOptions" />

        <template v-if="showPauses">
          <Marker
            v-for="(p, idx) in pauseMarkers"
            :key="`pause-${idx}`"
            :options="pauseMarkerOptionsList[idx]"
            @click="togglePausePopup(p, idx)"
          />
        </template>

        <CustomMarker v-if="activePopup" :options="{ position: activePopup.position, anchorPoint: 'BOTTOM_CENTER' }">
          <div
            class="bg-white rounded-md shadow-md px-3 py-2 text-xs leading-tight -translate-y-2 cursor-pointer"
            @click="closeActivePopup"
          >
            <template v-if="activePopup.type === 'interaction'">
              <div class="flex items-center gap-1.5 whitespace-nowrap">
                <span
                  class="inline-block h-2 w-2 rounded-full"
                  :style="{ backgroundColor: activePopup.inter.response_color }"
                />
                <span class="font-medium">{{ formatResponseLabel(activePopup.inter.response) }}</span>
                <span class="text-muted-foreground">· {{ formatInteractionTime(activePopup.inter.ts) }}</span>
                <span class="text-muted-foreground"
                  >· #{{ activePopup.sequence }} of {{ totalTrackedInteractions }}</span
                >
              </div>
              <FlaggedInteractionPopupBody v-if="showFraud" :fraud="activePopup.inter.fraud" />
              <div
                v-if="showAppFlags && activePopup.inter.app_flag_reasons?.length"
                class="mt-1.5 flex flex-wrap gap-1"
              >
                <span
                  v-for="reason in activePopup.inter.app_flag_reasons"
                  :key="reason"
                  :class="APP_FLAG_REASON_CHIP_CLASS"
                >
                  {{ reason }}
                </span>
              </div>
            </template>

            <template v-else-if="activePopup.type === 'pause'">
              <div class="flex flex-col gap-0.5 min-w-[180px]">
                <div class="font-semibold">Pause</div>
                <div>{{ formatTimeOfDay(activePopup.pause.start) }} → {{ formatTimeOfDay(activePopup.pause.end) }}</div>
                <div>Duration: {{ formatSecondsHuman(activePopup.pause.durationS) }}</div>
              </div>
            </template>

            <template v-else>
              <div class="flex flex-col gap-0.5 min-w-[200px]">
                <div class="font-semibold">Segment #{{ activePopup.segment.id }}</div>
                <div>
                  Score:
                  <span class="font-medium" :style="{ color: scoreToColor(activePopup.segment.score) }">
                    {{ activePopup.segment.score.toFixed(0) }}% ({{ fraudScoreBand(activePopup.segment.score).label }})
                  </span>
                </div>
                <div v-if="activePopup.segment.isSimulated" class="text-red-600 font-medium">Simulated</div>
                <div>Connection: {{ activePopup.segment.connectionType }}</div>
                <div>
                  Distance: {{ activePopup.segment.distanceM.toFixed(1) }} m /
                  {{ activePopup.segment.durationS.toFixed(1) }} s
                </div>
                <div>
                  Speed (GPS / sensor): {{ activePopup.segment.airSpeedMps.toFixed(2) }} /
                  {{ activePopup.segment.sensorSpeedMps.toFixed(2) }} m/s
                </div>
                <div v-if="activePopup.segment.reasons.length" class="text-muted-foreground mt-0.5">
                  Reasons: {{ activePopup.segment.reasons.join(', ') }}
                </div>
              </div>
            </template>
          </div>
        </CustomMarker>
      </GoogleMap>
    </div>

    <CanvassingTimeline
      v-if="validInteractions.length || routeSegments.length || motionActivitySegments.length"
      :interactions="validInteractions"
      :route-segments="routeSegments"
      :motion-activity-segments="motionActivitySegments"
      :selected-responses="selectedResponses"
      :active-id="activePopup?.id ?? null"
      :timezone="timezone"
      @select="toggleInteractionPopup"
      @window-change="brushedWindow = $event"
    />
  </div>
</template>

<script setup lang="ts">
import { GoogleMap, Marker, Polyline, CustomMarker } from 'vue3-google-map';
import type { InteractionPointView, MapBounds, MotionActivityBandView, RouteSegmentView, TimeSpan } from '~/client';
import { scoreToColor } from '~/utils/canvassing/segmentScore';
import {
  formatResponseLabel,
  formatInteractionTime,
  formatTimeOfDay,
  formatSecondsHuman,
} from '~/utils/canvassing/format';
import { isValidLatLng } from '~/utils/canvassing/coords';
import { fraudScoreBand } from '~/constants/reports/fraudScoreBands';
import { fraudSeverityConfig, getFraudSeverityStyle } from '~/constants/reports/fraudReportCards';
import { APP_FLAG_REASON_CHIP_CLASS } from '~/constants/workshifts/canvassingAppStatsConfig';

interface Props {
  interactions: InteractionPointView[];
  routeSegments?: RouteSegmentView[];
  motionActivitySegments?: MotionActivityBandView[];
  pauseIntervals?: TimeSpan[];
  mapBounds?: MapBounds | null;
  // When false, the map renders interactions only — no fraud severity rings,
  // canvasser-gap pins/lines, or fraud reason popup. Defaults to true so the
  // fraud report keeps its full overlay; the work-shift page opts out.
  showFraud?: boolean;
  // When true, interactions carrying canvassing-app-stats flags (app_flag_reasons)
  // get a red ring and the popup lists their reasons. Independent of showFraud —
  // the work-shift details map hides the old fraud overlay but shows these.
  showAppFlags?: boolean;
  // Tailwind height class(es) for the map canvas wrapper. The default keeps the
  // historical fixed height; flex consumers (work-shift review log) pass
  // "min-h-0 flex-1" to let the canvas fill their layout instead.
  heightClass?: string;
  // When false, the map's built-in clickable response legend is hidden — for
  // consumers that provide their own response filter (work-shift review log).
  showLegend?: boolean;
  // IANA timezone forwarded to the timeline axis (the shift's own time zone).
  timezone?: string;
}
const props = withDefaults(defineProps<Props>(), {
  routeSegments: () => [],
  motionActivitySegments: () => [],
  pauseIntervals: () => [],
  mapBounds: null,
  showFraud: true,
  showAppFlags: false,
  heightClass: 'h-[600px]',
  showLegend: true,
  timezone: undefined,
});

// Ring color for an app-stats-flagged interaction (red-600).
const APP_FLAG_RING_HEX = '#dc2626';

const selectedInteractionId = defineModel<number | null>('selectedInteractionId', { default: null });

const apiKey = String(useRuntimeConfig().public.googleMapApiKey);

const mapRef = useTemplateRef<{ ready: boolean; map?: any; api?: any }>('mapRef');

const showPauses = ref(true);
const selectedResponses = ref<string[]>([]);
const brushedWindow = ref<{ start: Date; end: Date } | null>(null);

const LABEL_MIN_ZOOM = 16;
const currentZoom = ref(13);
const showSequenceLabels = computed(() => currentZoom.value >= LABEL_MIN_ZOOM);

// Marker icon scales. `labeled` variants apply when the map is zoomed in past
// `LABEL_MIN_ZOOM` and a numeric sequence label is rendered inside the dot;
// `unlabeled` variants are the smaller markers used at low zoom levels.
const MARKER_SCALES = {
  labeledSelected: 13,
  labeledDefault: 11,
  unlabeledSelected: 7,
  unlabeledDefault: 6,
} as const;

// google.maps.SymbolPath numeric values — stable per Google Maps docs.
// CIRCLE = 0, FORWARD_CLOSED_ARROW = 3. Using the literals avoids a runtime
// dependency on `mapRef.value.api.SymbolPath` being resolved before render.
const SYMBOL_PATH_CIRCLE = 0;
const SYMBOL_PATH_FORWARD_CLOSED_ARROW = 3;

// Material "person" glyph for the canvasser pin.
const PERSON_PATH =
  'M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z';

const ARROW_REPEAT_PX = '200px';
const ARROW_BASE_SCALE = 1.8;
const RUN_GAP_MS = 5 * 60 * 1000;

const arrowIcons = [
  {
    icon: {
      path: SYMBOL_PATH_FORWARD_CLOSED_ARROW,
      scale: ARROW_BASE_SCALE,
      rotation: 180,
      strokeColor: '#1f2937',
      strokeOpacity: 0.9,
      strokeWeight: 1.5,
      fillColor: '#1f2937',
      fillOpacity: 0.9,
    },
    offset: '0%',
    repeat: ARROW_REPEAT_PX,
  },
];

function toggleSelectedResponse(response: string) {
  const idx = selectedResponses.value.indexOf(response);
  if (idx === -1) {
    selectedResponses.value = [...selectedResponses.value, response];
  } else {
    selectedResponses.value = selectedResponses.value.filter((r) => r !== response);
  }
}

const selectedResponseSet = computed(() => new Set(selectedResponses.value));

// Static initial values; the map fits to data programmatically once `ready` flips true.
const initialCenter = { lat: 0, lng: 0 };
const initialZoom = 13;

// The view-data model nests coordinates as Location objects (`location`,
// `canvasser_location`). Flatten them once to the lat/lon/canvasser_lat/canvasser_lon
// shape the map code works in (Google Maps wants {lat,lng}); every computed below
// narrows off this flattened list.
type FlatInteraction = InteractionPointView & {
  lat: number | null;
  lon: number | null;
  canvasser_lat: number | null;
  canvasser_lon: number | null;
};
const flatInteractions = computed<FlatInteraction[]>(() =>
  props.interactions.map((i) => ({
    ...i,
    lat: i.location?.latitude ?? null,
    lon: i.location?.longitude ?? null,
    canvasser_lat: i.canvasser_location?.latitude ?? null,
    canvasser_lon: i.canvasser_location?.longitude ?? null,
  }))
);

// Interactions that can be placed on the map. Non-located interactions (location
// null — e.g. a flagged NO_GPS interaction) are excluded here; they still appear
// in the flagged-interactions list. The guard narrows lat/lon to `number` so the
// downstream marker/bounds code doesn't have to null-check.
type LocatedInteraction = FlatInteraction & { lat: number; lon: number };
const hasMapCoords = (i: FlatInteraction): i is LocatedInteraction => isValidLatLng(i.lat, i.lon);
const validInteractions = computed<LocatedInteraction[]>(() => flatInteractions.value.filter(hasMapCoords));

// Flagged interactions that have BOTH a house location and a canvasser GPS point.
// Both endpoints are required to draw the gap line + place the pin. The backend only
// sets canvasser_* for flagged interactions, so this is implicitly "flagged only".
type CanvasserInteraction = LocatedInteraction & {
  canvasser_lat: number;
  canvasser_lon: number;
};
const canvasserPins = computed<CanvasserInteraction[]>(() => {
  // The canvasser pin + dashed gap line + distance label is a fraud-only overlay
  // (the backend sets canvasser_* only for flagged interactions). Suppress the
  // whole set when fraud display is off.
  if (!props.showFraud) return [];
  return flatInteractions.value.filter(
    (i): i is CanvasserInteraction => isValidLatLng(i.lat, i.lon) && isValidLatLng(i.canvasser_lat, i.canvasser_lon)
  );
});

function canvasserPinHex(i: CanvasserInteraction): string {
  return getFraudSeverityStyle(i.fraud?.severity).mapRingHex;
}

// Dashed connector house <-> canvasser, drawn as repeated dots over a transparent line.
function canvasserGapLineOptions(i: CanvasserInteraction) {
  return {
    path: [
      { lat: i.lat, lng: i.lon },
      { lat: i.canvasser_lat, lng: i.canvasser_lon },
    ],
    geodesic: true,
    strokeOpacity: 0,
    zIndex: 1,
    icons: [
      {
        icon: {
          path: SYMBOL_PATH_CIRCLE,
          fillColor: canvasserPinHex(i),
          fillOpacity: 1,
          strokeOpacity: 0,
          scale: 2,
        },
        offset: '0',
        repeat: '10px',
      },
    ],
  };
}

function canvasserMidpoint(i: CanvasserInteraction) {
  return { lat: (i.lat + i.canvasser_lat) / 2, lng: (i.lon + i.canvasser_lon) / 2 };
}

function formatGap(i: CanvasserInteraction): string {
  return `~${Math.round(i.canvasser_distance_m ?? 0)} m`;
}

function onCanvasserPinClick(i: CanvasserInteraction) {
  // Reuse the existing selection flow — selecting opens the fraud popup at the house
  // marker and pans the map (see interactionPopup / watchEffect below).
  otherPopup.value = null;
  localInteractionPopup.value = null;
  selectedInteractionId.value = selectedInteractionId.value === i.id ? null : (i.id ?? null);
}

// Display sequence number (1-based). Derived from the backend-assigned `id` so the
// same interaction shows the same number on the map and in the flagged list. Falls
// back to the local array index only for legacy data with no id.
function displaySequence(inter: InteractionPointView, fallbackIdx: number): number {
  return (inter.id ?? fallbackIdx) + 1;
}

interface InteractionLegendEntry {
  response: string;
  label: string;
  color: string;
  count: number;
}

const interactionLegend = computed<InteractionLegendEntry[]>(() => {
  const seen = new Map<string, InteractionLegendEntry>();
  for (const inter of validInteractions.value) {
    const existing = seen.get(inter.response);
    if (existing) {
      existing.count++;
    } else {
      seen.set(inter.response, {
        response: inter.response,
        label: formatResponseLabel(inter.response),
        color: inter.response_color,
        count: 1,
      });
    }
  }
  return Array.from(seen.values()).sort((a, b) => a.label.localeCompare(b.label));
});

const totalInteractions = computed(() => validInteractions.value.length);

// Denominator for the popup "#N of M" label. Uses the full tracked set (the same
// set the 1-based `id` indexes over), so a mapped interaction's number is never
// larger than the total — even when some tracked interactions are off-map.
const totalTrackedInteractions = computed(() => props.interactions.length);

const initialBounds = computed<{ south: number; west: number; north: number; east: number } | null>(() => {
  if (props.mapBounds) {
    return {
      south: props.mapBounds.south,
      west: props.mapBounds.west,
      north: props.mapBounds.north,
      east: props.mapBounds.east,
    };
  }
  let south = Infinity;
  let north = -Infinity;
  let west = Infinity;
  let east = -Infinity;
  let any = false;
  const visit = (lat: number, lon: number) => {
    if (lat < south) south = lat;
    if (lat > north) north = lat;
    if (lon < west) west = lon;
    if (lon > east) east = lon;
    any = true;
  };
  for (const seg of props.routeSegments) {
    if (isValidLatLng(seg.p1.lat, seg.p1.lon)) visit(seg.p1.lat, seg.p1.lon);
    if (isValidLatLng(seg.p2.lat, seg.p2.lon)) visit(seg.p2.lat, seg.p2.lon);
  }
  for (const inter of validInteractions.value) visit(inter.lat, inter.lon);
  if (!any) return null;
  return { south, west, north, east };
});

function buildInteractionMarkerOptions(inter: LocatedInteraction, sequenceNumber: number) {
  const set = selectedResponseSet.value;
  const hasSelection = set.size > 0;
  const isSelected = hasSelection && set.has(inter.response);
  const isDimmedByLegend = hasSelection && !isSelected;
  const w = brushedWindow.value;
  let isOutsideWindow = false;
  if (w) {
    const t = Date.parse(inter.ts);
    if (!Number.isNaN(t) && (t < w.start.getTime() || t > w.end.getTime())) {
      isOutsideWindow = true;
    }
  }
  const isDimmed = isDimmedByLegend || isOutsideWindow;
  const withLabel = showSequenceLabels.value;
  const scale = withLabel
    ? isSelected
      ? MARKER_SCALES.labeledSelected
      : MARKER_SCALES.labeledDefault
    : isSelected
      ? MARKER_SCALES.unlabeledSelected
      : MARKER_SCALES.unlabeledDefault;
  const appFlagged = props.showAppFlags && (inter.app_flag_reasons?.length ?? 0) > 0;
  const fraudRing = props.showFraud && inter.fraud;
  const ring = appFlagged
    ? APP_FLAG_RING_HEX
    : fraudRing
      ? fraudSeverityConfig[inter.fraud!.severity].mapRingHex
      : '#ffffff';
  const ringWeight = appFlagged || fraudRing ? 4 : 1.5;
  return {
    position: { lat: inter.lat, lng: inter.lon },
    zIndex: isSelected ? 2 : isDimmed ? 0 : 1,
    label: withLabel
      ? {
          text: String(sequenceNumber),
          color: isDimmed ? 'rgba(255,255,255,0.5)' : '#ffffff',
          fontSize: '10px',
          fontWeight: '700',
        }
      : null,
    icon: {
      path: SYMBOL_PATH_CIRCLE,
      fillColor: inter.response_color,
      fillOpacity: isDimmed ? 0.2 : 0.9,
      strokeColor: ring,
      strokeWeight: ringWeight,
      strokeOpacity: isDimmed ? 0.3 : 1,
      scale,
    },
  };
}

const interactionMarkerOptionsList = computed(() =>
  validInteractions.value.map((inter, idx) => buildInteractionMarkerOptions(inter, displaySequence(inter, idx)))
);

const routeEndpoints = computed<{
  start: { lat: number; lng: number } | null;
  end: { lat: number; lng: number } | null;
}>(() => {
  let start: { lat: number; lng: number } | null = null;
  let end: { lat: number; lng: number } | null = null;
  for (const seg of props.routeSegments) {
    if (!start && isValidLatLng(seg.p1.lat, seg.p1.lon)) start = { lat: seg.p1.lat, lng: seg.p1.lon };
    if (isValidLatLng(seg.p2.lat, seg.p2.lon)) end = { lat: seg.p2.lat, lng: seg.p2.lon };
  }
  if (!start && validInteractions.value.length) {
    const first = validInteractions.value[0];
    start = { lat: first.lat, lng: first.lon };
  }
  if (!end && validInteractions.value.length) {
    const last = validInteractions.value[validInteractions.value.length - 1];
    end = { lat: last.lat, lng: last.lon };
  }
  return { start, end };
});

const ENDPOINT_FLAG_LABEL = { color: '#ffffff', fontWeight: '700', fontSize: '13px' } as const;

const startFlagMarkerOptions = computed(() =>
  routeEndpoints.value.start
    ? { position: routeEndpoints.value.start, label: { ...ENDPOINT_FLAG_LABEL, text: 'A' }, zIndex: 5 }
    : null
);
const endFlagMarkerOptions = computed(() =>
  routeEndpoints.value.end
    ? { position: routeEndpoints.value.end, label: { ...ENDPOINT_FLAG_LABEL, text: 'B' }, zIndex: 5 }
    : null
);

interface PauseMarker {
  lat: number;
  lon: number;
  start: string;
  end: string;
  durationS: number;
}

const PAUSE_MARKER_MIN_SCALE = 5;
const PAUSE_MARKER_MAX_SCALE = 22;
const PAUSE_LOG_MIN_S = 30;
const PAUSE_LOG_MAX_S = 2 * 60 * 60;
const PAUSE_LOG_RANGE = Math.log10(PAUSE_LOG_MAX_S / PAUSE_LOG_MIN_S);

function pauseMarkerScale(durationS: number): number {
  if (!Number.isFinite(durationS) || durationS <= PAUSE_LOG_MIN_S) return PAUSE_MARKER_MIN_SCALE;
  const norm = Math.log10(durationS / PAUSE_LOG_MIN_S) / PAUSE_LOG_RANGE;
  const clamped = Math.max(0, Math.min(1, norm));
  return PAUSE_MARKER_MIN_SCALE + clamped * (PAUSE_MARKER_MAX_SCALE - PAUSE_MARKER_MIN_SCALE);
}

function buildPauseMarkerOptions(p: PauseMarker) {
  return {
    position: { lat: p.lat, lng: p.lon },
    icon: {
      path: SYMBOL_PATH_CIRCLE,
      fillColor: '#6b7280',
      fillOpacity: 0.45,
      strokeColor: '#374151',
      strokeWeight: 1.5,
      scale: pauseMarkerScale(p.durationS),
    },
    zIndex: 1,
  };
}

interface SegmentPopupData {
  id: string;
  score: number;
  isSimulated: boolean;
  connectionType: string;
  distanceM: number;
  durationS: number;
  airSpeedMps: number;
  sensorSpeedMps: number;
  reasons: string[];
}

interface SegmentPolyline {
  id: string;
  options: {
    path: { lat: number; lng: number }[];
    geodesic: boolean;
    strokeColor: string;
    strokeOpacity: number;
    strokeWeight: number;
    zIndex: number;
  };
  data: SegmentPopupData;
}

const segmentPolylines = computed<SegmentPolyline[]>(() => {
  const w = brushedWindow.value;
  const windowStart = w ? w.start.getTime() : null;
  const windowEnd = w ? w.end.getTime() : null;
  const out: SegmentPolyline[] = [];
  for (const seg of props.routeSegments) {
    const { p1, p2 } = seg;
    if (!isValidLatLng(p1.lat, p1.lon) || !isValidLatLng(p2.lat, p2.lon)) continue;
    let strokeOpacity = 0.5;
    if (windowStart !== null && windowEnd !== null) {
      const tStart = Date.parse(p1.ts);
      const tEnd = Date.parse(p2.ts);
      if (!Number.isNaN(tStart) && !Number.isNaN(tEnd) && (tEnd < windowStart || tStart > windowEnd)) {
        strokeOpacity = 0.1;
      }
    }
    out.push({
      id: String(seg.id),
      options: {
        path: [
          { lat: p1.lat, lng: p1.lon },
          { lat: p2.lat, lng: p2.lon },
        ],
        geodesic: false,
        strokeColor: scoreToColor(seg.score),
        strokeOpacity,
        strokeWeight: seg.is_simulated ? 5 : 4,
        zIndex: 1,
      },
      data: {
        id: String(seg.id),
        score: seg.score,
        isSimulated: seg.is_simulated,
        connectionType: seg.connection_type,
        distanceM: seg.distance_m,
        durationS: seg.duration_s,
        airSpeedMps: seg.air_speed_mps,
        sensorSpeedMps: seg.sensor_speed_mps,
        reasons: seg.reasons,
      },
    });
  }
  return out;
});

// Straight gray connectors across missing route stretches: when consecutive
// segments (in time order) don't share an endpoint, the recorded track has a
// hole (GPS dropout / server-side simplification). Bridging it with a neutral
// gray line keeps the route readable as one path without pretending the
// connector carries a fraud score.
const GAP_EPSILON_DEG = 0.00005; // ~5 m — endpoints closer than this count as connected

const gapConnectors = computed(() => {
  const segs = props.routeSegments
    .filter((seg) => isValidLatLng(seg.p1.lat, seg.p1.lon) && isValidLatLng(seg.p2.lat, seg.p2.lon))
    .slice()
    .sort((a, b) => Date.parse(a.p1.ts) - Date.parse(b.p1.ts));
  const out: {
    path: { lat: number; lng: number }[];
    geodesic: boolean;
    strokeColor: string;
    strokeOpacity: number;
    strokeWeight: number;
    zIndex: number;
  }[] = [];
  for (let i = 1; i < segs.length; i++) {
    const prev = segs[i - 1].p2;
    const next = segs[i].p1;
    if (Math.abs(prev.lat - next.lat) < GAP_EPSILON_DEG && Math.abs(prev.lon - next.lon) < GAP_EPSILON_DEG) continue;
    out.push({
      path: [
        { lat: prev.lat, lng: prev.lon },
        { lat: next.lat, lng: next.lon },
      ],
      geodesic: false,
      strokeColor: '#9ca3af',
      strokeOpacity: 0.7,
      strokeWeight: 3,
      zIndex: 0,
    });
  }
  return out;
});

const directionRuns = computed<{ lat: number; lng: number }[][]>(() => {
  if (!props.routeSegments.length) return [];
  const runs: { lat: number; lng: number }[][] = [];
  let currentRun: { lat: number; lng: number }[] = [];
  let lastTs: number | null = null;

  const flushRun = () => {
    if (currentRun.length >= 2) runs.push(currentRun);
    currentRun = [];
  };

  for (const seg of props.routeSegments) {
    const { p1, p2 } = seg;
    if (!isValidLatLng(p1.lat, p1.lon) || !isValidLatLng(p2.lat, p2.lon)) {
      flushRun();
      lastTs = null;
      continue;
    }
    const p1Ts = Date.parse(p1.ts);
    if (lastTs !== null && !Number.isNaN(p1Ts) && p1Ts - lastTs > RUN_GAP_MS) {
      flushRun();
    }
    if (currentRun.length === 0) currentRun.push({ lat: p1.lat, lng: p1.lon });
    currentRun.push({ lat: p2.lat, lng: p2.lon });
    const p2Ts = Date.parse(p2.ts);
    lastTs = Number.isNaN(p2Ts) ? null : p2Ts;
  }
  flushRun();
  return runs;
});

const interactionTrailPath = computed<{ lat: number; lng: number }[]>(() => {
  if (props.routeSegments.length) return [];
  if (validInteractions.value.length < 2) return [];
  return validInteractions.value.map((i) => ({ lat: i.lat, lng: i.lon }));
});

type InteractionPopup = {
  id: string;
  type: 'interaction';
  position: { lat: number; lng: number };
  inter: InteractionPointView;
  sequence: number;
};
type PausePopup = { id: string; type: 'pause'; position: { lat: number; lng: number }; pause: PauseMarker };
type SegmentPopup = { id: string; type: 'segment'; position: { lat: number; lng: number }; segment: SegmentPopupData };
type ActivePopup = InteractionPopup | PausePopup | SegmentPopup;

const otherPopup = ref<PausePopup | SegmentPopup | null>(null);

const localInteractionPopup = ref<InteractionPopup | null>(null);

const interactionPopup = computed<InteractionPopup | null>(() => {
  const id = selectedInteractionId.value;
  if (id == null) return localInteractionPopup.value;
  const idx = validInteractions.value.findIndex((i) => i.id === id);
  if (idx === -1) return null;
  const inter = validInteractions.value[idx];
  return {
    id: `interaction:${idx}`,
    type: 'interaction',
    position: { lat: inter.lat, lng: inter.lon },
    inter,
    sequence: displaySequence(inter, idx),
  };
});

const activePopup = computed<ActivePopup | null>(() => interactionPopup.value ?? otherPopup.value);

function closeActivePopup() {
  otherPopup.value = null;
  localInteractionPopup.value = null;
  selectedInteractionId.value = null;
}

function toggleInteractionPopup(inter: InteractionPointView, idx: number) {
  const key = `interaction:${idx}`;
  const isOpen = interactionPopup.value?.id === key;
  otherPopup.value = null;
  if (isOpen) {
    localInteractionPopup.value = null;
    selectedInteractionId.value = null;
    return;
  }
  if (inter.id != null) {
    localInteractionPopup.value = null;
    selectedInteractionId.value = inter.id;
  } else if (inter.location != null) {
    localInteractionPopup.value = {
      id: key,
      type: 'interaction',
      position: { lat: inter.location.latitude, lng: inter.location.longitude },
      inter,
      sequence: displaySequence(inter, idx),
    };
  }
}

function panMapTo(lat: number, lng: number) {
  const map = mapRef.value?.map;
  if (!map) return;
  map.panTo({ lat, lng });
}

watchEffect(() => {
  const popup = interactionPopup.value;
  if (popup && popup.inter.location != null) panMapTo(popup.inter.location.latitude, popup.inter.location.longitude);
});

// Clear a stale selection only when the id is unknown across ALL interactions —
// not just the mappable ones. A selected non-located interaction (no coords, list
// only) is legitimately absent from validInteractions and must stay selected.
watch([selectedInteractionId, () => props.interactions], ([id, list]) => {
  if (id == null) return;
  if (!list.some((i) => i.id === id)) selectedInteractionId.value = null;
});

function togglePausePopup(p: PauseMarker, idx: number) {
  const id = `pause:${idx}`;
  if (otherPopup.value?.id === id) {
    otherPopup.value = null;
    return;
  }
  localInteractionPopup.value = null;
  selectedInteractionId.value = null;
  otherPopup.value = { id, type: 'pause', position: { lat: p.lat, lng: p.lon }, pause: p };
}

function onSegmentClick(seg: SegmentPolyline, event: any) {
  const popupId = `segment:${seg.id}`;
  if (otherPopup.value?.id === popupId) {
    otherPopup.value = null;
    return;
  }
  const latLng = event?.latLng;
  if (!latLng) return;
  localInteractionPopup.value = null;
  selectedInteractionId.value = null;
  otherPopup.value = {
    id: popupId,
    type: 'segment',
    position: { lat: latLng.lat(), lng: latLng.lng() },
    segment: seg.data,
  };
}

function onZoomChange() {
  const z = mapRef.value?.map?.getZoom();
  if (typeof z === 'number') currentZoom.value = z;
}

watch(
  () => mapRef.value?.ready,
  async (ready) => {
    if (!ready) return;
    await nextTick();
    const map = mapRef.value?.map;
    const api = mapRef.value?.api;
    if (!map || !api) return;

    const initialZoomValue = map.getZoom();
    if (typeof initialZoomValue === 'number') currentZoom.value = initialZoomValue;

    const b = initialBounds.value;
    if (b) {
      map.fitBounds(new api.LatLngBounds(new api.LatLng(b.south, b.west), new api.LatLng(b.north, b.east)));
    }
  },
  { immediate: true }
);

const pauseMarkers = computed<PauseMarker[]>(() => {
  if (!props.pauseIntervals.length || !props.routeSegments.length) return [];

  const points: { lat: number; lon: number; t: number }[] = [];
  for (const seg of props.routeSegments) {
    if (isValidLatLng(seg.p1.lat, seg.p1.lon)) {
      const t = Date.parse(seg.p1.ts);
      if (!Number.isNaN(t)) points.push({ lat: seg.p1.lat, lon: seg.p1.lon, t });
    }
    if (isValidLatLng(seg.p2.lat, seg.p2.lon)) {
      const t = Date.parse(seg.p2.ts);
      if (!Number.isNaN(t)) points.push({ lat: seg.p2.lat, lon: seg.p2.lon, t });
    }
  }
  if (!points.length) return [];
  points.sort((a, b) => a.t - b.t);

  const findNearest = (t: number) => {
    let lo = 0;
    let hi = points.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (points[mid].t < t) lo = mid + 1;
      else hi = mid;
    }
    const before = points[lo - 1];
    const after = points[lo];
    if (!before) return after;
    if (!after) return before;
    return Math.abs(before.t - t) <= Math.abs(after.t - t) ? before : after;
  };

  return props.pauseIntervals
    .map((interval) => {
      const startT = Date.parse(interval.start);
      const endT = Date.parse(interval.end);
      if (Number.isNaN(startT) || Number.isNaN(endT)) return null;
      const nearest = findNearest(startT);
      if (!nearest) return null;
      return {
        lat: nearest.lat,
        lon: nearest.lon,
        start: interval.start,
        end: interval.end,
        durationS: Math.max(0, (endT - startT) / 1000),
      } satisfies PauseMarker;
    })
    .filter((p): p is PauseMarker => p !== null);
});

const pauseMarkerOptionsList = computed(() => pauseMarkers.value.map((p) => buildPauseMarkerOptions(p)));
</script>
