export interface FraudScoreBand {
  label: string;
  color: string;
  min: number;
}

// Score is in [0, 100]. Bands ordered ascending by `min`. Highest band whose `min <= score` wins.
export const fraudSegmentScoreBands: FraudScoreBand[] = [
  { label: 'Low', color: '#16a34a', min: 0 },
  { label: 'Medium', color: '#eab308', min: 40 },
  { label: 'High', color: '#f97316', min: 70 },
  { label: 'Critical', color: '#dc2626', min: 90 },
];

export function fraudScoreBand(score: number): FraudScoreBand {
  let band = fraudSegmentScoreBands[0];
  for (const candidate of fraudSegmentScoreBands) {
    if (score >= candidate.min) band = candidate;
  }
  return band;
}
