interface MotionActivityEntry {
  color: string;
  label: string;
}

const FALLBACK_COLOR = '#9ca3af'; // gray-400

export const motionActivityConfig: Record<string, MotionActivityEntry> = {
  stationary: { color: '#6b7280', label: 'Stationary' }, // slate-500
  walking: { color: '#22c55e', label: 'Walking' }, // green-500
  running: { color: '#15803d', label: 'Running' }, // green-700
  automotive: { color: '#3b82f6', label: 'Automotive' }, // blue-500
  cycling: { color: '#f97316', label: 'Cycling' }, // orange-500
  unknown: { color: '#eab308', label: 'Unknown' }, // yellow-500
};

export function getMotionActivityColor(activity: string): string {
  return motionActivityConfig[activity]?.color ?? FALLBACK_COLOR;
}

export function getMotionActivityLabel(activity: string): string {
  return motionActivityConfig[activity]?.label ?? activity;
}
